async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  let reachedEnd = false;

  try {
    const decoder = new TextDecoder("utf-8", {
      fatal: true,
      ignoreBOM: true,
    });

    let accepted = 0;
    let rejected = 0;
    let physicalLine = 1;
    let fragments = [];
    let bufferedLength = 0;

    const handleLine = async (tail, line) => {
      let lastByte;
      if (tail.length > 0) {
        lastByte = tail[tail.length - 1];
      } else if (fragments.length > 0) {
        const lastFragment = fragments[fragments.length - 1];
        lastByte = lastFragment[lastFragment.length - 1];
      }

      const removeCR = lastByte === 13;
      const length = bufferedLength + tail.length - (removeCR ? 1 : 0);
      let bytes;

      if (fragments.length === 0) {
        bytes = removeCR ? tail.subarray(0, tail.length - 1) : tail;
      } else {
        bytes = new Uint8Array(length);
        let offset = 0;

        for (const fragment of fragments) {
          const count = Math.min(fragment.length, length - offset);
          if (count > 0) {
            bytes.set(fragment.subarray(0, count), offset);
            offset += count;
          }
        }

        if (offset < length) {
          bytes.set(tail.subarray(0, length - offset), offset);
        }
      }

      fragments = [];
      bufferedLength = 0;

      const text = decoder.decode(bytes);
      if (text.trim() === "") {
        return true;
      }

      let value;
      try {
        value = JSON.parse(text);
      } catch (_) {
        rejected += 1;
        return true;
      }

      accepted += 1;
      return (await visitor({ line, value })) !== false;
    };

    for (;;) {
      const result = await reader.read();

      if (result.done) {
        reachedEnd = true;

        if (bufferedLength > 0) {
          const shouldContinue = await handleLine(new Uint8Array(0), physicalLine);
          if (!shouldContinue) {
            return { accepted, rejected, stopped: true };
          }
        }

        return { accepted, rejected, stopped: false };
      }

      const chunk = result.value;
      let start = 0;

      for (let index = 0; index < chunk.length; index += 1) {
        if (chunk[index] !== 10) {
          continue;
        }

        const shouldContinue = await handleLine(
          chunk.subarray(start, index),
          physicalLine,
        );

        if (!shouldContinue) {
          return { accepted, rejected, stopped: true };
        }

        physicalLine += 1;
        start = index + 1;
      }

      if (start < chunk.length) {
        const remainder = chunk.slice(start);
        fragments.push(remainder);
        bufferedLength += remainder.length;
      }
    }
  } finally {
    try {
      if (!reachedEnd) {
        await reader.cancel();
      }
    } finally {
      reader.releaseLock();
    }
  }
}
